begin;
set local statement_timeout='30s';
set local lock_timeout='5s';
do $$
declare owner_user uuid:=gen_random_uuid(); viewer_user uuid:=gen_random_uuid(); member_user uuid:=gen_random_uuid();external_user uuid:=gen_random_uuid();
 w uuid; other_w uuid; obj uuid; foreign_obj uuid; a uuid; b uuid; foreign_rec uuid; shared_list uuid; hidden_list uuid;
 doc_a uuid:=gen_random_uuid();doc_b uuid:=gen_random_uuid();portal uuid;wf uuid;version bigint;n integer;result jsonb;
begin
 insert into auth.users(id,email,aud,role,email_confirmed_at)
 select u,'reader-fixture-'||u||'@example.invalid','authenticated','authenticated',now() from unnest(array[owner_user,viewer_user,member_user,external_user]) u;
 perform set_config('request.jwt.claim.sub',owner_user::text,true);
 w:=public.create_workspace('Reader rollback fixture');other_w:=public.create_workspace('Foreign reader rollback');
 insert into public.memberships(workspace_id,user_id,role) values(w,viewer_user,'viewer'),(w,member_user,'member');
 select id into obj from public.objects where workspace_id=w and slug='companies';
 select id into foreign_obj from public.objects where workspace_id=other_w and slug='companies';
 insert into public.records(workspace_id,object_id,display_name,amount) values(w,obj,'Authorized company',10) returning id into a;
 insert into public.records(workspace_id,object_id,display_name,amount) values(w,obj,'Hidden company',99999) returning id into b;
 insert into public.records(workspace_id,object_id,display_name) values(other_w,foreign_obj,'Foreign') returning id into foreign_rec;
 insert into public.record_relations(workspace_id,source_id,target_id) values(w,a,b);
 insert into public.tasks(workspace_id,record_id,title) values(w,a,'Authorized task'),(w,b,'Hidden task'),(w,null,'Unlinked task');
 insert into public.notes(workspace_id,record_id,content,private,author_id) values(w,a,'Public authorized note',false,owner_user),(w,a,'Private authorized note',true,owner_user),(w,b,'Hidden note',false,owner_user);
 insert into public.documents(id,workspace_id,record_id,name,path,mime,size) values(doc_a,w,a,'Authorized.pdf',w::text||'/'||doc_a||'.pdf','application/pdf',1),(doc_b,w,b,'Hidden.pdf',w::text||'/'||doc_b||'.pdf','application/pdf',1);
 insert into storage.objects(bucket_id,name) values('relay-documents',w::text||'/'||doc_a||'.pdf'),('relay-documents',w::text||'/'||doc_b||'.pdf');
 insert into public.lists(workspace_id,object_id,name) values(w,obj,'Authorized list') returning id into shared_list;
 insert into public.lists(workspace_id,object_id,name) values(w,obj,'Hidden list') returning id into hidden_list;
 insert into public.list_entries(workspace_id,list_id,record_id) values(w,shared_list,a),(w,shared_list,b),(w,hidden_list,b);
 insert into public.workflows(workspace_id,name,definition) values(w,'Hidden automation','{"steps":[]}') returning id into wf;
 insert into public.workflow_runs(workspace_id,workflow_id,workflow_version,mode,snapshot) values(w,wf,1,'simulation',jsonb_build_object('hidden_record',b));
 insert into public.import_jobs(workspace_id,object_id,filename,digest,inserted,skipped) values(w,obj,'Hidden.csv',repeat('f',64),0,0);
 insert into public.portals(workspace_id,record_id,name,enabled) values(w,a,'Portal fixture',true) returning id into portal;
 insert into public.portal_members(workspace_id,portal_id,email,user_id) values(w,portal,'reader-fixture-'||viewer_user||'@example.invalid',viewer_user);
 insert into public.portal_members(workspace_id,portal_id,email,user_id) values(w,portal,'reader-fixture-'||external_user||'@example.invalid',external_user);
 insert into public.portal_items(workspace_id,portal_id,title,document_id) values(w,portal,'Hidden document',doc_b);
 execute 'set local role authenticated';
 perform set_config('request.jwt.claim.sub',viewer_user::text,true);
 if exists(select 1 from public.records where workspace_id=w) then raise exception 'New reader has default broad access';end if;
 begin perform public.team_reader_access_set(w,viewer_user,1,'all','{}');raise exception 'Reader self-escalation allowed';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',owner_user::text,true);
 begin perform public.team_reader_access_set(w,viewer_user,1,'selected',array[foreign_rec]);raise exception 'Foreign record accepted';exception when invalid_parameter_value then null;end;
 perform public.team_reader_access_set(w,viewer_user,1,'selected',array[a]);
 begin perform public.team_reader_access_set(w,viewer_user,1,'all','{}');raise exception 'Stale visibility version accepted';exception when serialization_failure then null;end;
 result:=public.team_reader_access_get(w,viewer_user);
 if jsonb_array_length(result->'records')<>1 or result->'member'->>'reader_scope'<>'selected' then raise exception 'Admin access editor response wrong';end if;
 perform set_config('request.jwt.claim.sub',viewer_user::text,true);
 if (select count(*) from public.records where workspace_id=w)<>1 or exists(select 1 from public.records where id=b) then raise exception 'Record scope leaked';end if;
 if (select sum(amount) from public.records where workspace_id=w)<>10 then raise exception 'Report totals leaked hidden records';end if;
 if (select count(*) from public.tasks where workspace_id=w)<>1 then raise exception 'Related or detached task leak';end if;
 if (select count(*) from public.notes where workspace_id=w)<>1 then raise exception 'Private/hidden note leaked';end if;
 if exists(select 1 from public.record_relations where workspace_id=w) then raise exception 'Hidden relationship leaked';end if;
 if (select count(*) from public.documents where workspace_id=w)<>1 then raise exception 'Document scope leaked';end if;
 if exists(select 1 from storage.objects where bucket_id='relay-documents' and name=w::text||'/'||doc_b||'.pdf') then raise exception 'Hidden file download allowed';end if;
 if not exists(select 1 from storage.objects where bucket_id='relay-documents' and name=w::text||'/'||doc_a||'.pdf') then raise exception 'Authorized file blocked';end if;
 if (select count(*) from public.lists where workspace_id=w)<>1 or (select count(*) from public.list_entries where workspace_id=w)<>1 then raise exception 'List scope leaked or recursed';end if;
 if exists(select 1 from public.audit_events where workspace_id=w and entity_id=b) then raise exception 'Hidden record audit leaked';end if;
 if relay_private.reader_audit_allowed(w,'tasks',gen_random_uuid(),jsonb_build_object('record_id',b,'title','Secret'),jsonb_build_object('record_id',a)) or relay_private.reader_audit_allowed(w,'tasks',gen_random_uuid(),jsonb_build_object('record_id',a),jsonb_build_object('record_id',b)) then raise exception 'Reassigned task history leaked';end if;
 if exists(select 1 from public.workflow_runs where workspace_id=w) or exists(select 1 from public.import_jobs where workspace_id=w) then raise exception 'Operational snapshot leaked';end if;
 if relay_private.portal_access(portal) or exists(select 1 from public.portal_items where portal_id=portal) then raise exception 'Portal bypassed reader scope';end if;
 update public.records set display_name='Forged' where id=a;get diagnostics n=row_count;if n<>0 then raise exception 'Reader wrote record';end if;
 begin perform record_id from relay_private.reader_record_access limit 1;raise exception 'Private ACL table exposed';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',member_user::text,true);
 if (select count(*) from public.records where workspace_id=w)<>2 then raise exception 'Normal member access regressed';end if;
 begin perform public.team_reader_access_set(w,viewer_user,2,'all','{}');raise exception 'Member modified visibility';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',owner_user::text,true);
 perform public.team_reader_access_set(w,viewer_user,2,'all','{}');
 perform set_config('request.jwt.claim.sub',viewer_user::text,true);
 if (select count(*) from public.records where workspace_id=w)<>2 then raise exception 'Full reader mode failed';end if;
 perform set_config('request.jwt.claim.sub',owner_user::text,true);
 perform public.team_reader_access_set(w,viewer_user,3,'selected','{}');
 perform set_config('request.jwt.claim.sub',viewer_user::text,true);
 if exists(select 1 from public.records where workspace_id=w) then raise exception 'Revoked scope remains accessible with old JWT';end if;
 perform set_config('request.jwt.claim.sub',owner_user::text,true);
 perform public.team_member_change(w,viewer_user,'member',4);
 perform public.team_member_change(w,viewer_user,'viewer',5);
 perform set_config('request.jwt.claim.sub',viewer_user::text,true);
 if exists(select 1 from public.records where workspace_id=w) then raise exception 'Role downgrade restored old broad permissions';end if;
 perform set_config('request.jwt.claim.sub',external_user::text,true);
 if not exists(select 1 from public.portals where id=portal) or not exists(select 1 from public.portal_items where portal_id=portal) then raise exception 'External portal access regressed';end if;
 if not exists(select 1 from storage.objects where bucket_id='relay-documents' and name=w::text||'/'||doc_b||'.pdf') then raise exception 'Explicit external portal document blocked';end if;
 if exists(select 1 from public.records where workspace_id=w) then raise exception 'External portal gained CRM access';end if;
 execute 'reset role';
end $$;
rollback;
select 'Reader RLS, files, related data, reports, private notes, snapshots, stale versions, tenant isolation and revocation passed; fixtures rolled back' as result;
